<?php require 'config.php';require_login();$s=$pdo->prepare('SELECT * FROM orders WHERE user_id=? ORDER BY id DESC');$s->execute([$_SESSION['user_id']]);$orders=$s->fetchAll();?><!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="style.css"></head><body><div class="wrap"><div class="card"><h1>My orders and shipping status</h1><?php foreach($orders as $o):?><div class="card"><h3>Order #<?=h($o['id'])?></h3><p>Total: <?=money($o['total'])?> · Payment: <?=h($o['payment_status'])?></p><p><b>Delivery status:</b> <?=h($o['status'])?></p><p><?=h($o['shipping_name'])?>, <?=h($o['address'])?>, <?=h($o['city'])?> - <?=h($o['postal_code'])?></p><a href="order.php?id=<?=$o['id']?>">View order details / Update address</a></div><?php endforeach;?></div></div></body></html>